-- Staging-only release: chat-based support and independent purchase/payment workflow.
insert into private.it_support_services(key,label,kind,approval)values('office','مشاكل البرامج المكتبية','service',false),('suggestion','اقتراحات','service',false)on conflict(key)do update set label=excluded.label,approval=false;
update private.it_support_services set label=case key when 'network_fault'then 'مشاكل الشبكة والإنترنت'when 'device_fault'then 'مشاكل الأجهزة والطابعات وأجهزة البصمة'when 'system_fault'then 'مشاكل نظام أودو'else label end;
alter table private.it_support_settings add column chief_accountant_id uuid references public.profiles(id);
insert into private.access_catalog(key,module,label,operation,scopes,sort_order)values('it_support.accounting','دعم تقنية المعلومات','مراجعة أوامر الصرف وإحالتها للمحاسب','accounting',array['all'],112),('it_support.pay','دعم تقنية المعلومات','صرف أوامر الشراء التقنية المسندة','pay',array['all'],113);
alter table private.it_support_tickets add column client_token uuid,add column escalation_to text not null default '',add column sla_paused_at timestamptz,add column sla_paused_seconds numeric not null default 0,add column sla_paused_minutes numeric not null default 0;
create unique index it_support_client_token_idx on private.it_support_tickets(requester_id,client_token)where client_token is not null;
alter table private.it_support_messages add column system_event boolean not null default false;
alter table private.it_support_files add column message_id bigint references private.it_support_messages(id);
create index it_support_files_message_idx on private.it_support_files(message_id);
create table private.it_purchase_requests(
 ticket_id uuid primary key references private.it_support_tickets(id),quote_provider text not null check(quote_provider in('employee','specialist')),
 phase text not null default 'quote'check(phase in('quote','technical','manager','supply','receipt','receipt_issue','payment','closed','cancelled','rejected')),
 manager_id uuid not null references public.profiles(id),finance_approver_id uuid not null references public.profiles(id),chief_id uuid not null references public.profiles(id),
 quantity int not null check(quantity between 1 and 10000),supplier text not null default '',supplier_reference text not null default '',
 total numeric(14,2)check(total>0),quote_file uuid references private.it_support_files(id),quote_version int not null default 0,
 quote_history jsonb not null default '[]',approved_version int,invoice_file uuid references private.it_support_files(id),received_at timestamptz,received_quantity int,
 received_note text not null default '',supplier_verified_by uuid references public.profiles(id),closed_at timestamptz
);
create table private.it_purchase_payments(
 id uuid primary key default gen_random_uuid(),ticket_id uuid not null references private.it_purchase_requests(ticket_id),kind text not null check(kind in('advance','balance')),
 amount numeric(14,2)not null check(amount>0),state text not null default 'technical'check(state in('technical','supervisor','chief','assigned','paid','cancelled')),
 accountant_id uuid references public.profiles(id),quote_version int not null,invoice_file uuid references private.it_support_files(id),
 supplier_snapshot text not null,reason text not null,revision int not null default 1,created_at timestamptz not null default now(),paid_at timestamptz,proof_file uuid references private.it_support_files(id),reference text
);
create unique index it_purchase_one_payment_kind on private.it_purchase_payments(ticket_id,kind)where state<>'cancelled';
create index it_purchase_manager_idx on private.it_purchase_requests(manager_id);
create index it_purchase_finance_idx on private.it_purchase_requests(finance_approver_id);
create index it_purchase_chief_idx on private.it_purchase_requests(chief_id);
create index it_purchase_quote_idx on private.it_purchase_requests(quote_file);
create index it_purchase_invoice_idx on private.it_purchase_requests(invoice_file);
create index it_payment_ticket_idx on private.it_purchase_payments(ticket_id);
create index it_payment_accountant_idx on private.it_purchase_payments(accountant_id);
create index it_payment_proof_idx on private.it_purchase_payments(proof_file);
create index it_payment_invoice_idx on private.it_purchase_payments(invoice_file);
do $$declare n text;begin foreach n in array array['it_purchase_requests','it_purchase_payments']loop execute format('alter table private.%I enable row level security',n);execute format('revoke all on private.%I from public,anon,authenticated',n);execute format('create policy internal_only on private.%I to authenticated using(false)with check(false)',n);end loop;end$$;
-- Functions below are private checked commands; wrappers are invoker-only.
create function private.it_actor_ready(p_id uuid)returns boolean language sql stable security definer set search_path=pg_catalog,private,public as $$select exists(select 1 from public.profiles where id=p_id and active and status='active'and(role='admin'or'it_support'=any(allowed_modules)))$$;
create function private.it_purchase_manager(p_requester uuid)returns uuid language plpgsql stable security definer set search_path=pg_catalog,private,public as $$declare u uuid;seen uuid[]:=array[p_requester];begin select manager_id into u from public.profiles where id=p_requester;while u is not null and not(u=any(seen))loop if private.it_actor_ready(u)then return u;end if;seen:=array_append(seen,u);select manager_id into u from public.profiles where id=u;end loop;raise exception 'لا يوجد مشرف مستقل ومفعّل لاعتماد الطلب؛ راجع مسؤول النظام';end$$;
create or replace function private.it_support_visible(ticket uuid)returns boolean language sql stable security definer set search_path=pg_catalog,private,public as $$select private.module_allowed('it_support')and exists(select 1 from private.it_support_tickets t where t.id=ticket and(auth.uid()in(t.requester_id,t.beneficiary_id,t.approver_id)or private.it_support_permission('it_support.operate')or private.it_support_permission('it_support.supervise')or exists(select 1 from private.it_purchase_requests p where p.ticket_id=t.id and auth.uid()in(p.manager_id,p.finance_approver_id,p.chief_id))or exists(select 1 from private.it_purchase_payments pay where pay.ticket_id=t.id and pay.accountant_id=auth.uid()and private.it_support_permission('it_support.pay'))))$$;
create function private.it_support_upload_allowed(ticket uuid)returns boolean language sql stable security definer set search_path=pg_catalog,private,public as $$select private.it_support_visible(ticket)and exists(select 1 from private.it_support_tickets t where t.id=ticket and t.state not in('closed','cancelled','rejected')and(auth.uid()in(t.requester_id,t.beneficiary_id)or private.it_support_permission('it_support.operate')or exists(select 1 from private.it_purchase_requests p where p.ticket_id=t.id and p.chief_id=auth.uid())or exists(select 1 from private.it_purchase_payments p where p.ticket_id=t.id and p.accountant_id=auth.uid()and p.state='assigned'and private.it_support_permission('it_support.pay'))))$$;
create function private.it_support_capacity(p_user uuid,p_exclude uuid default null)returns jsonb language sql stable security definer set search_path=pg_catalog,private as $$select jsonb_build_object('regular',count(*)filter(where priority<>1),'emergency',count(*)filter(where priority=1),'total',count(*),'resolved',count(*)filter(where state='resolved'))from private.it_support_tickets where(p_exclude is null or id<>p_exclude)and(p_user=requester_id or p_user=beneficiary_id)and service_key not in('purchase','suggestion')and state not in('closed','cancelled','rejected')$$;
create function private.it_support_capacity_check(p_requester uuid,p_beneficiary uuid,p_priority int,p_exclude uuid default null)returns void language plpgsql security definer set search_path=pg_catalog,private,public as $$declare u uuid;c jsonb;begin
-- The same ordered profile locks protect creation, reprioritization and reopening from parallel bypasses.
perform 1 from public.profiles where id in(p_requester,p_beneficiary)order by id for update;
for u in select distinct x from unnest(array[p_requester,p_beneficiary])x loop c:=private.it_support_capacity(u,p_exclude);if(c->>'total')::int>=5 or(p_priority=1 and(c->>'emergency')::int>=2)or(p_priority<>1 and(c->>'regular')::int>=3)then raise exception 'بلغ حد البلاغات المفتوحة: 3 غير طارئة و2 طارئة. أغلق البلاغات التي تم حلها أولًا أو تابع البلاغ القائم.'using errcode='P0001',detail=c::text;end if;end loop;end$$;
create function private.it_support_system(p_ticket uuid,p_body text)returns void language sql security definer set search_path=pg_catalog,private as $$insert into private.it_support_messages(ticket_id,actor_id,body,system_event)values(p_ticket,auth.uid(),p_body,true)$$;
create function private.it_support_link_files(p_ticket uuid,p_message bigint,p_ids jsonb)returns void language plpgsql security definer set search_path=pg_catalog,private as $$begin
if p_ids is null then return;end if;if jsonb_typeof(p_ids)<>'array'or jsonb_array_length(p_ids)>20 then raise exception 'المرفقات غير صالحة';end if;
if exists(select 1 from jsonb_array_elements_text(p_ids)x where not exists(select 1 from private.it_support_files f where f.id=x.value::uuid and f.ticket_id=p_ticket and f.uploader_id=auth.uid()and f.ready and(f.message_id is null or f.message_id=p_message)))then raise exception 'مرفق غير متاح لهذه الرسالة'using errcode='42501';end if;
update private.it_support_files set message_id=p_message where id in(select value::uuid from jsonb_array_elements_text(p_ids));end$$;
create function private.it_support_file_ok(p_file uuid,p_ticket uuid)returns boolean language sql stable security definer set search_path=pg_catalog,private as $$select exists(select 1 from private.it_support_files where id=p_file and ticket_id=p_ticket and ready)$$;

create index it_purchase_supplier_verifier_idx on private.it_purchase_requests(supplier_verified_by);

create index it_settings_chief_idx on private.it_support_settings(chief_accountant_id);
create index it_settings_specialist_idx on private.it_support_settings(specialist_id);
create index it_settings_supervisor_idx on private.it_support_settings(supervisor_id);

create function private.it_work_add(p_start timestamptz,p_minutes numeric)returns timestamptz language plpgsql stable security invoker set search_path=pg_catalog,private as $$declare cfg private.it_support_settings;d date;c timestamp;ending timestamp;n numeric:=p_minutes;avail numeric;begin
if p_start is null then return null;end if;if n<=0 then return p_start;end if;select * into strict cfg from private.it_support_settings;c:=p_start at time zone 'Asia/Riyadh';d:=c::date;
for i in 1..3660 loop
if extract(dow from d)::int=any(cfg.work_days)and to_char(d,'MM-DD')not in('02-22','09-23')and not exists(select 1 from private.recruitment_holidays h where h.day=d)then c:=greatest(c,d+cfg.work_start);ending:=d+cfg.work_end;avail:=greatest(0,extract(epoch from(ending-c))/60);if avail>=n then return(c+n*interval '1 minute')at time zone 'Asia/Riyadh';end if;n:=n-avail;end if;d:=d+1;c:=d+cfg.work_start;end loop;raise exception 'تعذر حساب تقويم العمل';end$$;
create function private.it_work_minutes(p_start timestamptz,p_end timestamptz)returns numeric language plpgsql stable security invoker set search_path=pg_catalog,private as $$declare cfg private.it_support_settings;d date;n numeric:=0;a timestamp:=p_start at time zone 'Asia/Riyadh';b timestamp:=p_end at time zone 'Asia/Riyadh';begin
if p_start is null or p_end<=p_start then return 0;end if;select * into strict cfg from private.it_support_settings;d:=a::date;while d<=b::date loop if extract(dow from d)::int=any(cfg.work_days)and to_char(d,'MM-DD')not in('02-22','09-23')and not exists(select 1 from private.recruitment_holidays h where h.day=d)then n:=n+greatest(0,extract(epoch from(least(b,d+cfg.work_end)-greatest(a,d+cfg.work_start)))/60);end if;d:=d+1;end loop;return n;end$$;
create or replace function private.it_support_deadline()returns trigger language plpgsql security invoker set search_path=pg_catalog,private as $$declare sec numeric:=0;mins numeric:=0;begin
if new.service_key='purchase'then new.sla_started_at:=null;new.due_at:=null;return new;end if;
if tg_op='INSERT'then new.sla_started_at:=new.created_at;new.due_at:=private.it_support_due(new.created_at,new.priority);return new;end if;
if old.sla_paused_at is not null and new.state<>'waiting_employee'then sec:=greatest(0,extract(epoch from(now()-old.sla_paused_at)));mins:=private.it_work_minutes(old.sla_paused_at,now());new.sla_paused_seconds:=old.sla_paused_seconds+sec;new.sla_paused_minutes:=old.sla_paused_minutes+mins;new.sla_paused_at:=null;end if;
if new.priority<>old.priority then new.due_at:=private.it_support_due(new.sla_started_at,new.priority);if new.priority=1 then new.due_at:=new.due_at+new.sla_paused_seconds*interval '1 second';else new.due_at:=private.it_work_add(new.due_at,new.sla_paused_minutes);end if;
elsif sec>0 then if new.priority=1 then new.due_at:=old.due_at+sec*interval '1 second';else new.due_at:=private.it_work_add(old.due_at,mins);end if;end if;
if new.state='waiting_employee'and old.state<>'waiting_employee'then new.sla_paused_at:=now();end if;return new;end$$;
create or replace trigger it_support_deadline before insert or update of state,priority on private.it_support_tickets for each row execute function private.it_support_deadline();
-- Do not invent a historical pause duration; begin pausing existing waiting requests at rollout.
update private.it_support_tickets set sla_paused_at=now()where state='waiting_employee'and sla_paused_at is null;
create or replace function private.it_support_create(p_data jsonb)returns uuid language plpgsql security definer set search_path=pg_catalog,private,public as $$declare cfg private.it_support_settings;b public.profiles;beneficiary uuid:=coalesce(nullif(p_data->>'beneficiary_id','')::uuid,auth.uid());kind text:=p_data->>'service_key';pri int:=coalesce(nullif(p_data->>'priority','')::int,4);i uuid;token uuid:=nullif(p_data->>'client_token','')::uuid;manager uuid;fin uuid;chief uuid;begin
perform private.require_module('it_support');select * into strict cfg from private.it_support_settings;
if not private.it_actor_ready(cfg.specialist_id)or not private.it_actor_ready(cfg.supervisor_id)then raise exception 'راجع إعداد مسؤولي الدعم في الحسابات والصلاحيات';end if;
select * into strict b from public.profiles where id=beneficiary and active and status='active';if b.id<>auth.uid()and b.manager_id is distinct from auth.uid()then raise exception 'الطلب لنفسك أو لفريقك المباشر فقط'using errcode='42501';end if;
perform 1 from public.profiles where id in(auth.uid(),b.id)order by id for update;
if token is not null then select id into i from private.it_support_tickets where requester_id=auth.uid()and client_token=token;if i is not null then return i;end if;end if;
if kind not in('network_fault','device_fault','system_fault','office','suggestion','purchase')or kind is null or pri not between 1 and 4 then raise exception 'اختر تصنيفًا وأولوية صحيحين';end if;
if kind='suggestion'and pri<>4 then raise exception 'الاقتراحات بأولوية عادية فقط';end if;
if kind not in('suggestion','purchase')then
if pri=1 and coalesce(p_data->>'work_stopped','false')<>'true'then raise exception 'الأولوية الطارئة مخصصة لتوقف العمل';end if;perform private.it_support_capacity_check(auth.uid(),b.id,pri);end if;
if kind='purchase'then
manager:=private.it_purchase_manager(auth.uid());fin:=case when cfg.supervisor_id=auth.uid()then private.it_purchase_manager(auth.uid())else cfg.supervisor_id end;chief:=case when cfg.chief_accountant_id=auth.uid()then private.it_purchase_manager(auth.uid())else cfg.chief_accountant_id end;
if not private.it_actor_ready(chief)then raise exception 'رئيس الحسابات غير مضبوط أو غير مفعل للتجربة';end if;
if coalesce(p_data->>'quote_provider','')not in('employee','specialist')then raise exception 'حدد من يوفر عرض السعر';end if;end if;
insert into private.it_support_tickets(requester_id,beneficiary_id,approver_id,specialist_id,supervisor_id,service_key,title,description,impact,urgency,priority,state,client_token)values(auth.uid(),b.id,manager,cfg.specialist_id,cfg.supervisor_id,kind,p_data->>'title',p_data->>'description',1,1,case when kind='purchase'then 4 else pri end,'new',token)returning id into i;
if kind='purchase'then insert into private.it_purchase_requests(ticket_id,quote_provider,manager_id,finance_approver_id,chief_id,quantity)values(i,p_data->>'quote_provider',manager,fin,chief,(p_data->>'quantity')::int);end if;
insert into private.it_support_events(ticket_id,actor_id,action)values(i,auth.uid(),'created');perform private.it_support_notify(i);return i;end$$;
create or replace function private.it_support_action(p_id uuid,p_revision int,p_action text,p_data jsonb)returns void language plpgsql security definer set search_path=pg_catalog,private,public as $$declare t private.it_support_tickets;n text;note text:=btrim(coalesce(p_data->>'note',''));op boolean:=private.it_support_permission('it_support.operate');mid bigint;pri int;begin
if not private.it_support_visible(p_id)then raise exception 'الطلب غير متاح'using errcode='42501';end if;
select * into strict t from private.it_support_tickets where id=p_id;
perform 1 from public.profiles where id in(t.requester_id,t.beneficiary_id)order by id for update;
select * into strict t from private.it_support_tickets where id=p_id for update;
if t.revision<>p_revision then raise exception 'تم تحديث الطلب؛ أعد تحميله'using errcode='40001';end if;
if length(note)<2 then raise exception 'اكتب الرسالة أو التوضيح';end if;n:=t.state;
if p_action='comment'and t.state not in('closed','cancelled','rejected')then
if coalesce((p_data->>'internal')::boolean,false)and not(op or private.it_support_permission('it_support.supervise'))then raise exception 'الملاحظات الداخلية للدعم والإشراف فقط'using errcode='42501';end if;
if coalesce((p_data->>'internal')::boolean,false)and coalesce(jsonb_array_length(p_data->'file_ids'),0)>0 then raise exception 'مرفقات المحادثة متاحة للمشاركين؛ لا ترفقها بملاحظة داخلية';end if;
insert into private.it_support_messages(ticket_id,actor_id,body,internal)values(t.id,auth.uid(),note,coalesce((p_data->>'internal')::boolean,false))returning id into mid;perform private.it_support_link_files(t.id,mid,p_data->'file_ids');
if t.state='waiting_employee'and auth.uid()in(t.requester_id,t.beneficiary_id)and not coalesce((p_data->>'internal')::boolean,false)then n:='working';end if;
elsif t.service_key='purchase'then raise exception 'استخدم إجراء مرحلة طلب الشراء';
elsif p_action in('working','waiting_employee','waiting_vendor','resolve')and op and t.state in('new','working','waiting_employee','waiting_vendor')then
n:=case p_action when 'resolve'then 'resolved'else p_action end;if p_action='resolve'and length(note)<10 then raise exception 'وضح الحل بعشرة أحرف على الأقل';end if;
if p_action='waiting_vendor'and length(btrim(coalesce(p_data->>'escalation_to','')))<2 then raise exception 'حدد الجهة المصعد إليها';end if;
perform private.it_support_system(t.id,case p_action when 'working'then 'جارٍ المعالجة'when 'waiting_employee'then 'بانتظار معلومات إضافية'when 'waiting_vendor'then 'تم تصعيد المشكلة إلى '||(p_data->>'escalation_to')else 'تم الحل — بانتظار تأكيد الموظف'end||': '||note);
elsif p_action='priority'and op and t.state not in('closed','cancelled','rejected')then
pri:=(p_data->>'priority')::int;if pri is null or pri not between 1 and 4 or(t.service_key='suggestion'and pri<>4)then raise exception 'الأولوية غير صالحة';end if;
if t.service_key<>'suggestion'then perform private.it_support_capacity_check(t.requester_id,t.beneficiary_id,pri,t.id);end if;
update private.it_support_tickets set priority=pri where id=t.id;perform private.it_support_system(t.id,'تم تعديل الأولوية مع توضيح السبب: '||note);
elsif p_action='close'and t.state='resolved'and auth.uid()=(case when t.beneficiary_id=t.specialist_id then t.supervisor_id else t.beneficiary_id end) then
n:='closed';if(p_data->>'rating')::int not between 1 and 5 or p_data->>'rating'is null then raise exception 'اختر تقييم الخدمة من 1 إلى 5';end if;perform private.it_support_system(t.id,'أكد الموظف الحل وأغلق الطلب: '||note);
elsif p_action='reopen'and t.state in('resolved','closed')and auth.uid()=t.beneficiary_id then
if t.state='closed'and t.service_key<>'suggestion'then perform private.it_support_capacity_check(t.requester_id,t.beneficiary_id,t.priority,t.id);end if;n:='working';perform private.it_support_system(t.id,'المشكلة مستمرة — أعيد الطلب للمعالجة: '||note);
elsif p_action='cancel'and t.state in('new','working','waiting_employee','waiting_vendor')and auth.uid()=t.requester_id then n:='cancelled';perform private.it_support_system(t.id,'ألغى الموظف الطلب: '||note);
else raise exception 'الإجراء غير متاح لك في المرحلة الحالية'using errcode='42501';end if;
update private.it_support_tickets set state=n,state_since=case when state<>n then now()else state_since end,solution=case when p_action='resolve'then note else solution end,escalation_to=case when p_action='waiting_vendor'then p_data->>'escalation_to'else escalation_to end,resolved_at=case when p_action='resolve'then now()when p_action='reopen'then null else resolved_at end,rating=case when p_action='close'then(p_data->>'rating')::int when p_action='reopen'then null else rating end,revision=revision+1,updated_at=now()where id=t.id;
insert into private.it_support_events(ticket_id,actor_id,action,note)values(t.id,auth.uid(),p_action,note);perform private.it_support_notify(t.id);end$$;

create function private.it_purchase_payment_owner(p_id uuid)returns uuid language sql stable security definer set search_path=pg_catalog,private as $$select case pay.state when 'technical'then t.specialist_id when 'supervisor'then p.finance_approver_id when 'chief'then p.chief_id when 'assigned'then pay.accountant_id end from private.it_purchase_payments pay join private.it_purchase_requests p on p.ticket_id=pay.ticket_id join private.it_support_tickets t on t.id=p.ticket_id where pay.id=p_id$$;
create function private.it_purchase_close_if_complete(p_ticket uuid)returns void language plpgsql security definer set search_path=pg_catalog,private as $$declare p private.it_purchase_requests;paid numeric;begin select * into strict p from private.it_purchase_requests where ticket_id=p_ticket;
select coalesce(sum(amount),0)into paid from private.it_purchase_payments where ticket_id=p.ticket_id and state='paid';
if p.received_at is not null and private.it_support_file_ok(p.invoice_file,p.ticket_id)and paid=p.total and not exists(select 1 from private.it_purchase_payments where ticket_id=p.ticket_id and state not in('paid','cancelled'))then update private.it_purchase_requests set phase='closed',closed_at=now()where ticket_id=p.ticket_id;update private.it_support_tickets set state='closed',updated_at=now(),revision=revision+1 where id=p.ticket_id;perform private.it_support_system(p.ticket_id,'اكتمل الاستلام والصرف وتسوية المستندات؛ أُغلق طلب الشراء');end if;end$$;
create function private.it_purchase_make_payment(p_ticket uuid,p_kind text,p_amount numeric,p_reason text)returns uuid language plpgsql security definer set search_path=pg_catalog,private as $$declare p private.it_purchase_requests;reserved numeric;i uuid;begin
select * into strict p from private.it_purchase_requests where ticket_id=p_ticket for update;
if p.approved_version is distinct from p.quote_version or p.total is null or p_amount is null or p_amount<=0 then raise exception 'عرض شراء معتمد مطلوب قبل طلب الصرف';end if;
if p_kind='balance'and(p.received_at is null or not private.it_support_file_ok(p.invoice_file,p.ticket_id))then raise exception 'تأكيد الاستلام والفاتورة مطلوبان قبل صرف الرصيد';end if;
select coalesce(sum(amount),0)into reserved from private.it_purchase_payments where ticket_id=p_ticket and state<>'cancelled';if reserved+p_amount>p.total then raise exception 'مجموع أوامر الصرف يتجاوز عرض الشراء المعتمد';end if;
insert into private.it_purchase_payments(ticket_id,kind,amount,quote_version,invoice_file,supplier_snapshot,reason)values(p_ticket,p_kind,p_amount,p.quote_version,p.invoice_file,p.supplier,p_reason)returning id into i;
perform private.it_support_system(p_ticket,case p_kind when 'advance'then 'إنشاء طلب صرف مقدم للمورد'else 'إنشاء طلب صرف رصيد المورد تلقائيًا بعد الاستلام'end);return i;end$$;
create function private.it_purchase_action(p_id uuid,p_revision int,p_action text,p_data jsonb)returns void language plpgsql security definer set search_path=pg_catalog,private,public as $$declare t private.it_support_tickets;p private.it_purchase_requests;note text:=btrim(coalesce(p_data->>'note',''));op boolean:=private.it_support_permission('it_support.operate');amount numeric;reserved numeric;file uuid;begin
if not private.it_support_visible(p_id)then raise exception 'الطلب غير متاح'using errcode='42501';end if;
select * into strict t from private.it_support_tickets where id=p_id for update;select * into strict p from private.it_purchase_requests where ticket_id=p_id for update;
if t.revision<>p_revision then raise exception 'تم تحديث الطلب؛ أعد التحميل'using errcode='40001';end if;
if p.phase in('closed','cancelled','rejected')then raise exception 'طلب الشراء منتهٍ';end if;
if p_action='quote'and((p.quote_provider='employee'and auth.uid()=t.requester_id)or op)and p.phase in('quote','technical','manager','supply')then
if exists(select 1 from private.it_purchase_payments where ticket_id=p_id and state<>'cancelled')then raise exception 'يوجد طلب صرف قائم؛ لا يمكن تغيير العرض حتى معالجته محاسبيًا';end if;
file:=(p_data->>'quote_file')::uuid;amount:=(p_data->>'total')::numeric;
if not private.it_support_file_ok(file,p_id)or amount is null or amount<=0 or amount>999999999999 or length(btrim(coalesce(p_data->>'supplier','')))<3 then raise exception 'أرفق عرض السعر وحدد المورد والقيمة الإجمالية الصحيحة';end if;
update private.it_purchase_requests set quote_history=quote_history||case when quote_file is not null then jsonb_build_array(jsonb_build_object('version',quote_version,'total',total,'supplier',supplier,'quote_file',quote_file,'approved_version',approved_version))else '[]'::jsonb end,total=amount,supplier=btrim(p_data->>'supplier'),supplier_reference=btrim(coalesce(p_data->>'supplier_reference','')),quote_file=file,quote_version=quote_version+1,approved_version=null,supplier_verified_by=null,phase='technical'where ticket_id=p_id;
perform private.it_support_system(p_id,'توفير / تحديث عرض السعر؛ أُعيد للمراجعة الفنية واعتماد المشرف');
elsif p_action='technical_approve'and op and p.phase='technical'then
if not private.it_support_file_ok(p.quote_file,p_id)then raise exception 'عرض السعر غير مكتمل';end if;update private.it_purchase_requests set phase='manager'where ticket_id=p_id;perform private.it_support_system(p_id,'راجع أخصائي التقنية المواصفات وعرض السعر وأحاله للمشرف المباشر');
elsif p_action='manager_approve'and p.phase='manager'and auth.uid()=p.manager_id and auth.uid()<>t.requester_id then
update private.it_purchase_requests set phase='supply',approved_version=quote_version where ticket_id=p_id;perform private.it_support_system(p_id,'اعتمد المشرف المباشر الشراء وفق نسخة عرض السعر الحالية');
elsif p_action='return'and((p.phase='technical'and op)or(p.phase='manager'and auth.uid()=p.manager_id))then
if length(note)<5 then raise exception 'وضح المطلوب استكماله';end if;update private.it_purchase_requests set phase='quote',approved_version=null where ticket_id=p_id;perform private.it_support_system(p_id,'أعيد طلب الشراء لاستكمال العرض: '||note);
elsif p_action='reject'and p.phase='manager'and auth.uid()=p.manager_id and auth.uid()<>t.requester_id then
if length(note)<5 then raise exception 'وضح سبب الرفض';end if;update private.it_purchase_requests set phase='rejected'where ticket_id=p_id;update private.it_support_tickets set state='rejected'where id=p_id;perform private.it_support_system(p_id,'رفض المشرف طلب الشراء: '||note);
elsif p_action='invoice'and op and p.phase in('supply','receipt','receipt_issue','payment')then
file:=(p_data->>'invoice_file')::uuid;if not private.it_support_file_ok(file,p_id)then raise exception 'أرفق الفاتورة أولًا';end if;
if exists(select 1 from private.it_purchase_payments where ticket_id=p_id and kind='balance'and state<>'cancelled')then raise exception 'الفاتورة مرتبطة بطلب صرف قائم ولا يمكن استبدالها';end if;
update private.it_purchase_requests set invoice_file=file where ticket_id=p_id;
if p.received_at is not null then
select coalesce(sum(pp.amount),0)into reserved from private.it_purchase_payments pp where pp.ticket_id=p_id and state<>'cancelled';if p.total>reserved then perform private.it_purchase_make_payment(p_id,'balance',p.total-reserved,'رصيد شراء بعد تأكيد الاستلام والفاتورة');end if;update private.it_purchase_requests set phase='payment'where ticket_id=p_id;
end if;perform private.it_support_system(p_id,'إرفاق فاتورة المورد لطلبات الصرف والتسوية');
elsif p_action='supplied'and op and p.phase in('supply','receipt_issue')then
update private.it_purchase_requests set phase='receipt'where ticket_id=p_id;perform private.it_support_system(p_id,'تم توفير الطلب — بانتظار تأكيد استلام الموظف');
elsif p_action='receive'and p.phase='receipt'and auth.uid()=t.beneficiary_id then
if (p_data->>'received_quantity')::int is null or (p_data->>'received_quantity')::int not between 0 and p.quantity then raise exception 'كمية الاستلام غير صحيحة';end if;
if(p_data->>'received_quantity')::int is distinct from p.quantity or coalesce(p_data->>'good_condition','false')<>'true'then
if length(note)<5 then raise exception 'وضح النقص أو المشكلة في الاستلام';end if;update private.it_purchase_requests set phase='receipt_issue',received_note=note,received_quantity=(p_data->>'received_quantity')::int where ticket_id=p_id;perform private.it_support_system(p_id,'سجل الموظف ملاحظة استلام؛ أوقف صرف الرصيد لحين المعالجة: '||note);
else
update private.it_purchase_requests set received_at=now(),received_quantity=p.quantity,received_note=note,phase='payment'where ticket_id=p_id;
if private.it_support_file_ok(p.invoice_file,p_id)then select coalesce(sum(pp.amount),0)into reserved from private.it_purchase_payments pp where pp.ticket_id=p_id and state<>'cancelled';if p.total>reserved then perform private.it_purchase_make_payment(p_id,'balance',p.total-reserved,'رصيد بعد استلام الموظف كامل الطلب');end if;end if;perform private.it_support_system(p_id,'أكد الموظف الاستلام كاملًا وبحالة سليمة');
end if;
elsif p_action='advance'and op and p.phase='supply'then
amount:=(p_data->>'amount')::numeric;if length(note)<10 then raise exception 'وثق اشتراط المورد للدفعة المقدمة';end if;perform private.it_purchase_make_payment(p_id,'advance',amount,note);
elsif p_action='cancel'and((auth.uid()=t.requester_id and p.phase in('quote','technical','manager'))or(op and p.phase in('quote','technical','manager','supply')))then
if length(note)<5 or exists(select 1 from private.it_purchase_payments where ticket_id=p_id and state<>'cancelled')then raise exception 'وضح سبب الإلغاء؛ لا يلغى طلب مرتبط بصرف قائم';end if;update private.it_purchase_requests set phase='cancelled'where ticket_id=p_id;update private.it_support_tickets set state='cancelled'where id=p_id;perform private.it_support_system(p_id,'إلغاء طلب الشراء: '||note);
else raise exception 'الإجراء ليس من صلاحيتك أو لا يناسب المرحلة الحالية'using errcode='42501';end if;
update private.it_support_tickets set state=case when state in('closed','cancelled','rejected')then state else 'working'end,revision=revision+1,updated_at=now(),state_since=now()where id=p_id;
perform private.it_purchase_close_if_complete(p_id);insert into private.it_support_events(ticket_id,actor_id,action,note)values(p_id,auth.uid(),'purchase_'||p_action,note);perform private.it_support_notify(p_id);end$$;
create function private.it_purchase_payment_action(p_id uuid,p_revision int,p_action text,p_data jsonb)returns void language plpgsql security definer set search_path=pg_catalog,private,public as $$declare pay private.it_purchase_payments;p private.it_purchase_requests;t private.it_support_tickets;ticket uuid;owner uuid;n text;note text:=btrim(coalesce(p_data->>'note',''));accountant uuid;begin
select ticket_id into strict ticket from private.it_purchase_payments where id=p_id;if not private.it_support_visible(ticket)then raise exception 'أمر الصرف غير متاح'using errcode='42501';end if;
select * into strict t from private.it_support_tickets where id=ticket for update;select * into strict p from private.it_purchase_requests where ticket_id=ticket for update;select * into strict pay from private.it_purchase_payments where id=p_id for update;
if pay.revision<>p_revision then raise exception 'تم تحديث أمر الصرف؛ أعد التحميل'using errcode='40001';end if;owner:=private.it_purchase_payment_owner(pay.id);
if owner is distinct from auth.uid()or not private.it_actor_ready(owner)then raise exception 'الإجراء لدى مسؤول المرحلة المحدد'using errcode='42501';end if;
if p.phase in('closed','cancelled','rejected')or pay.quote_version is distinct from p.approved_version then raise exception 'أمر الصرف لا يطابق نسخة الشراء المعتمدة';end if;
if pay.kind='balance'and(p.received_at is null or not private.it_support_file_ok(pay.invoice_file,ticket))then raise exception 'الفاتورة وتأكيد الاستلام مطلوبان لصرف الرصيد';end if;
if p_action='approve'and pay.state in('technical','supervisor')then
if pay.state='technical'and not private.it_support_permission('it_support.operate')then raise exception 'المراجعة الفنية لأخصائي التقنية'using errcode='42501';end if;
n:=case pay.state when 'technical'then 'supervisor'else 'chief'end;update private.it_purchase_payments set state=n,revision=revision+1 where id=pay.id;
perform private.it_support_system(ticket,case n when 'supervisor'then 'راجع أخصائي التقنية طلب الصرف وأحاله لمحمد باسنبل'else 'اعتماد طلب الصرف وإحالته لرئيس الحسابات'end);
elsif p_action='assign'and pay.state='chief'then
if not private.it_support_permission('it_support.accounting')and not(t.requester_id=(select chief_accountant_id from private.it_support_settings)and p.chief_id<>t.requester_id)then raise exception 'إحالة الصرف من اختصاص رئيس الحسابات'using errcode='42501';end if;
accountant:=(p_data->>'accountant_id')::uuid;if accountant in(t.requester_id,t.beneficiary_id,t.specialist_id,p.finance_approver_id,p.chief_id)or not exists(select 1 from public.profiles where id=accountant and active and status='active'and'it_support'=any(allowed_modules)and'it_support.pay'=any(permissions))then raise exception 'حدد محاسب صرف مستقل ومفعّل من قائمة الصلاحيات';end if;
if length(p.supplier_reference)<3 or p.supplier_verified_by is distinct from p.chief_id then raise exception 'وثّق مرجع المورد المعتمد لدى المالية قبل الإحالة';end if;
update private.it_purchase_payments set state='assigned',accountant_id=accountant,revision=revision+1 where id=pay.id;perform private.it_support_system(ticket,'راجع رئيس الحسابات المستندات وحدد المحاسب المعني للصرف');
elsif p_action='supplier_reference'and pay.state='chief'then
if length(btrim(coalesce(p_data->>'supplier_reference','')))<3 then raise exception 'أدخل مرجع المورد المعتمد';end if;update private.it_purchase_requests set supplier_reference=btrim(p_data->>'supplier_reference'),supplier_verified_by=auth.uid()where ticket_id=ticket;update private.it_purchase_payments set revision=revision+1 where id=pay.id;perform private.it_support_system(ticket,'وثّق رئيس الحسابات مرجع المورد المعتمد لدى المالية');
elsif p_action='pay'and pay.state='assigned'and private.it_support_permission('it_support.pay')then
if length(btrim(coalesce(p_data->>'reference','')))<4 or not private.it_support_file_ok((p_data->>'proof_file')::uuid,ticket)then raise exception 'مرجع التحويل وإثبات الصرف إلزاميان';end if;
update private.it_purchase_payments set state='paid',reference=btrim(p_data->>'reference'),proof_file=(p_data->>'proof_file')::uuid,paid_at=now(),revision=revision+1 where id=pay.id;
perform private.it_support_system(ticket,case pay.kind when 'advance'then 'أثبت المحاسب صرف الدفعة المقدمة؛ الطلب مستمر حتى الاستلام والتسوية'else 'أثبت المحاسب صرف رصيد المورد'end);
elsif p_action='return'and pay.state in('supervisor','chief','assigned')then
if length(note)<5 then raise exception 'وضح المطلوب مراجعته';end if;update private.it_purchase_payments set state='technical',accountant_id=null,revision=revision+1 where id=pay.id;perform private.it_support_system(ticket,'أعيد طلب الصرف لأخصائي التقنية: '||note);
else raise exception 'إجراء الصرف غير متاح'using errcode='42501';end if;
update private.it_support_tickets set revision=revision+1,updated_at=now()where id=ticket;perform private.it_purchase_close_if_complete(ticket);insert into private.it_support_events(ticket_id,actor_id,action,note)values(ticket,auth.uid(),'payment_'||p_action,note);perform private.it_support_notify(ticket);end$$;

create function private.it_support_owner(p_ticket uuid)returns uuid language plpgsql stable security definer set search_path=pg_catalog,private as $$declare t private.it_support_tickets;p private.it_purchase_requests;u uuid;begin select * into strict t from private.it_support_tickets where id=p_ticket;if t.state in('closed','cancelled','rejected')then return null;end if;
if t.service_key='purchase'then select * into strict p from private.it_purchase_requests where ticket_id=t.id;return case p.phase when 'quote'then case p.quote_provider when 'employee'then t.requester_id else t.specialist_id end when 'technical'then t.specialist_id when 'manager'then p.manager_id when 'supply'then t.specialist_id when 'receipt'then t.beneficiary_id when 'receipt_issue'then t.specialist_id when 'payment'then coalesce((select private.it_purchase_payment_owner(id)from private.it_purchase_payments where ticket_id=t.id and state not in('paid','cancelled')order by created_at limit 1),t.specialist_id)end;end if;
return case when t.state in('waiting_employee','resolved')then case when t.beneficiary_id=t.specialist_id then t.supervisor_id else t.beneficiary_id end else t.specialist_id end;end$$;
create or replace function private.it_support_notify(ticket uuid)returns void language plpgsql security definer set search_path=pg_catalog,private,public as $$declare t private.it_support_tickets;u uuid;begin select * into strict t from private.it_support_tickets where id=ticket;for u in select distinct x from unnest(array[t.requester_id,t.beneficiary_id,private.it_support_owner(ticket),case when t.priority=1 and t.service_key<>'purchase'then t.supervisor_id end])x where x is not null and x<>auth.uid()loop if private.it_actor_ready(u)then insert into public.notifications(recipient_id,type,title,message)values(u,'IT_SUPPORT','تحديث طلب IT-'||t.number,'يوجد تحديث في محادثة الطلب أو إجراء مطلوب منك.');end if;end loop;end$$;
create or replace function private.it_support_context()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,private,public as $$begin perform private.require_module('it_support');return jsonb_build_object('user_id',auth.uid(),'operator',private.it_support_permission('it_support.operate'),'supervisor',private.it_support_permission('it_support.supervise'),'accounting',private.it_support_permission('it_support.accounting'),'pay',private.it_support_permission('it_support.pay'),'admin',exists(select 1 from public.profiles where id=auth.uid()and role='admin'),'settings',(select to_jsonb(s)from private.it_support_settings s),'capacity',private.it_support_capacity(auth.uid()),'services',(select jsonb_agg(to_jsonb(s)order by key)from private.it_support_services s where key in('network_fault','device_fault','system_fault','office','suggestion')),'people',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'full_name',full_name,'manager_id',manager_id,'operate',role='admin'or'it_support.operate'=any(permissions),'supervise',role='admin'or'it_support.supervise'=any(permissions),'accounting','it_support.accounting'=any(permissions),'pay','it_support.pay'=any(permissions))order by full_name),'[]')from public.profiles where active and status='active'and(id=auth.uid()or private.it_support_permission('it_support.operate')or private.it_support_permission('it_support.supervise')or private.it_support_permission('it_support.accounting')or 'it_support.pay'=any(permissions)or id in(select specialist_id from private.it_support_settings)or id in(select supervisor_id from private.it_support_settings))));end$$;
create or replace function private.it_support_list()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,private,public as $$begin perform private.require_module('it_support');return(select coalesce(jsonb_agg(to_jsonb(q)order by priority,created_at desc),'[]')from(select t.*,b.full_name beneficiary_name,o.full_name owner_name,private.it_support_owner(t.id)owner_id,p.phase purchase_phase,p.quote_provider,p.total purchase_total,(select count(*)from private.it_support_files f where f.ticket_id=t.id and f.ready)attachment_count from private.it_support_tickets t join public.profiles b on b.id=t.beneficiary_id left join private.it_purchase_requests p on p.ticket_id=t.id left join public.profiles o on o.id=private.it_support_owner(t.id)where private.it_support_visible(t.id)order by t.created_at desc limit 500)q);end$$;
create or replace function private.it_support_detail(p_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,private,public as $$begin if not private.it_support_visible(p_id)then raise exception 'الطلب غير متاح'using errcode='42501';end if;return jsonb_build_object('ticket',(select to_jsonb(t)||jsonb_build_object('owner_id',private.it_support_owner(t.id))from private.it_support_tickets t where id=p_id),'purchase',(select to_jsonb(p)from private.it_purchase_requests p where ticket_id=p_id),'payments',(select coalesce(jsonb_agg(to_jsonb(p)||jsonb_build_object('owner_id',private.it_purchase_payment_owner(p.id))order by p.created_at),'[]')from private.it_purchase_payments p where ticket_id=p_id),'messages',(select coalesce(jsonb_agg(to_jsonb(m)||jsonb_build_object('actor_name',p.full_name)order by m.id),'[]')from private.it_support_messages m join public.profiles p on p.id=m.actor_id where ticket_id=p_id and(not internal or private.it_support_permission('it_support.operate')or private.it_support_permission('it_support.supervise'))),'files',(select coalesce(jsonb_agg(to_jsonb(f)-'uploader_id'order by created_at),'[]')from private.it_support_files f where ticket_id=p_id and ready),'can_upload',private.it_support_upload_allowed(p_id),'events',case when exists(select 1 from public.profiles where id=auth.uid()and role='admin')then(select coalesce(jsonb_agg(to_jsonb(e)order by id),'[]')from private.it_support_events e where ticket_id=p_id)else '[]'::jsonb end);end$$;
create function private.it_purchase_configure(p_chief uuid)returns void language plpgsql security definer set search_path=pg_catalog,private,public as $$begin
if not private.it_support_permission('it_support.supervise')or not exists(select 1 from public.profiles where id=auth.uid()and role='admin')then raise exception 'الإعدادات من إدارة المستخدمين والصلاحيات فقط'using errcode='42501';end if;
if not private.it_actor_ready(p_chief)or not exists(select 1 from public.profiles where id=p_chief and'it_support.accounting'=any(permissions))then raise exception 'حدد رئيس حسابات مفعلًا بصلاحية مراجعة الصرف';end if;update private.it_support_settings set chief_accountant_id=p_chief;end$$;
create function public.it_purchase_action(p_id uuid,p_revision int,p_action text,p_data jsonb)returns void language sql security invoker set search_path=pg_catalog,private as $$select private.it_purchase_action(p_id,p_revision,p_action,p_data)$$;
create function public.it_purchase_payment_action(p_id uuid,p_revision int,p_action text,p_data jsonb)returns void language sql security invoker set search_path=pg_catalog,private as $$select private.it_purchase_payment_action(p_id,p_revision,p_action,p_data)$$;
create function public.it_purchase_configure(p_chief uuid)returns void language sql security invoker set search_path=pg_catalog,private as $$select private.it_purchase_configure(p_chief)$$;
-- Patch the existing private Storage commands, retaining their MIME/size/ownership controls.
do $$declare body text;begin
body:=pg_get_functiondef('private.it_support_file_prepare(uuid,text,text,bigint)'::regprocedure);body:=replace(body,$q$not(auth.uid()in(t.requester_id,t.beneficiary_id)or private.it_support_permission('it_support.operate'))$q$,$q$not private.it_support_upload_allowed(t.id)$q$);execute body;
body:=pg_get_functiondef('private.it_support_file_access(text,boolean)'::regprocedure);body:=replace(body,$q$(auth.uid()in(t.requester_id,t.beneficiary_id)or private.it_support_permission('it_support.operate'))$q$,$q$ private.it_support_upload_allowed(t.id) $q$);execute body;end$$;
-- Private helper functions are not RPC endpoints. Only checked commands/policy predicates are executable by clients.
do $$declare f record;begin for f in select p.oid::regprocedure signature,p.proname,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private')and(p.proname like 'it_support_%'or p.proname like 'it_purchase_%'or p.proname in('it_actor_ready','it_work_add','it_work_minutes'))loop
execute format('revoke all on function %s from public,anon,authenticated',f.signature);
if f.proname in('it_support_create','it_support_action','it_support_context','it_support_list','it_support_detail','it_support_configure','it_support_calendar','it_support_file_prepare','it_support_file_finish','it_support_file_abort','it_support_file_access','it_purchase_action','it_purchase_payment_action','it_purchase_configure')then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end$$;
